import pandas as pd,numpy as np
from scipy.optimize import least_squares
def load(f):
    d=pd.read_csv(f); return d.iloc[::5].reset_index(drop=True)
files=['train/A_vref_op1.csv','train/A_vref_op3.csv','train/A_amb_op1.csv','train/A_amb_op2.csv','train/A_gentrip_op1.csv','train/A_fault_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv']
D={f:load(f) for f in files}
dt=0.005
def simQ(p,d):
    Kp,Kq,t1,Ki,Ti=p
    t1=abs(t1)+1e-3; Ti=abs(Ti)+1e-3
    V=d.voltage_pu.values; S=d.voltage_setpoint_pu.values
    Q=d.reactive_power_pu.values; V0=V[0]; Q0=Q[0]
    xf=0.0; xi=0.0; out=np.zeros(len(V))
    for i in range(len(V)):
        out[i]=xf+xi
        # fast lagged Q response to Vset error, plus integral
        xf+=dt*((Kp*(S[i]-V0)-Kq*(V[i]-V0))-xf)/t1
        xi+=dt*(Ki*(S[i]-V[i])-xi/Ti)
    return Q0+out
def res(p):
    return np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in files])
best=None
for t1 in [0.1,0.5]:
  for Ti in [1,5]:
    r=least_squares(res,[2.5,2.5,t1,1,Ti],bounds=([-50,-50,0.001,-100,0.01],[50,50,20,100,200]))
    if best is None or r.cost<best.cost: best=r
r=best
print(r.x,np.std(r.fun))
for f in files: print(f,np.std(simQ(r.x,D[f])-D[f].reactive_power_pu.values).round(4))

